    /// A noun form.
    pub fn noun_scored(&self, word: &str, case: Case, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (case, number,) {
            (Case::Nominative, Number::Singular,) => Some(0),
            (Case::Nominative, Number::Dual,) => Some(1),
            (Case::Nominative, Number::Plural,) => Some(2),
            (Case::Genitive, Number::Singular,) => Some(3),
            (Case::Genitive, Number::Dual,) => Some(4),
            (Case::Genitive, Number::Plural,) => Some(5),
            (Case::Dative, Number::Singular,) => Some(6),
            (Case::Dative, Number::Dual,) => Some(7),
            (Case::Dative, Number::Plural,) => Some(8),
            (Case::Accusative, Number::Singular,) => Some(9),
            (Case::Accusative, Number::Dual,) => Some(10),
            (Case::Accusative, Number::Plural,) => Some(11),
            (Case::Vocative, Number::Singular,) => Some(12),
            (Case::Vocative, Number::Dual,) => Some(13),
            (Case::Vocative, Number::Plural,) => Some(14),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form. The best candidate; the word itself if nothing is known.
    pub fn noun(&self, word: &str, case: Case, number: Number) -> String {
        best(self.noun_scored(word, case, number), word)
    }

    /// Scored gender of a noun.
